NooriEditor::~NooriEditor(){stopTimer();setLookAndFeel(nullptr);}
void NooriEditor::setupSlider(juce::Slider& s,juce::Label& l,juce::String label,double min,double max,double step,juce::String suffix){addAndMakeVisible(s);addAndMakeVisible(l);l.setText(label,juce::dontSendNotification);l.setColour(juce::Label::textColourId,muted);s.setRange(min,max,step);s.setTextBoxStyle(juce::Slider::TextBoxRight,false,75,20);s.setTextValueSuffix(suffix);s.onValueChange=[this]{pullControls();};}
void NooriEditor::syncControls(){auto s=session->settings;grid.setSelectedId(s.division==4?1:s.division==8?2:s.division==16?3:4,juce::dontSendNotification);rhythm.setSelectedId((int)s.rhythm+1,juce::dontSendNotification);mode.setSelectedId(s.naturalNaat?2:1,juce::dontSendNotification);sensitivity.setValue(s.sensitivity*100,juce::dontSendNotification);strength.setValue(s.strength*100,juce::dontSendNotification);humanize.setValue(s.humanizeMs,juce::dontSendNotification);tolerance.setValue(s.toleranceMs,juce::dontSendNotification);swing.setValue(s.swing*100,juce::dontSendNotification);offset.setValue(s.offsetMs,juce::dontSendNotification);sampleAccurate.setToggleState(s.sampleAccurate,juce::dontSendNotification);breath.setToggleState(s.breathProtection,juce::dontSendNotification);consonant.setToggleState(s.consonantProtection,juce::dontSendNotification);vowel.setToggleState(s.vowelProtection,juce::dontSendNotification);emotion.setToggleState(s.emotionalProtection,juce::dontSendNotification);}
void NooriEditor::pullControls(){auto& s=session->settings;s.division=grid.getSelectedId()==1?4:grid.getSelectedId()==2?8:grid.getSelectedId()==3?16:32;s.rhythm=(noori::Settings::Rhythm)(rhythm.getSelectedId()-1);s.naturalNaat=mode.getSelectedId()==2;s.sensitivity=sensitivity.getValue()/100;s.strength=strength.getValue()/100;s.humanizeMs=humanize.getValue();s.toleranceMs=tolerance.getValue();s.swing=swing.getValue()/100;s.offsetMs=offset.getValue();s.sampleAccurate=sampleAccurate.getToggleState();s.breathProtection=breath.getToggleState();s.consonantProtection=consonant.getToggleState();s.vowelProtection=vowel.getToggleState();s.emotionalProtection=emotion.getToggleState();waveform.repaint();}
void NooriEditor::bindSession(std::shared_ptr<EditSession> s){if(s==session)return;session=std::move(s);viewStart=0;viewFraction=1;zoom.setValue(1,juce::dontSendNotification);syncControls();updateScroll();}
void NooriEditor::timerCallback(){
#if JucePlugin_Enable_ARA
 if(processor.isEditorView()){if(auto s=selectedARASession(processor))bindSession(s);}
#endif
 const bool busy=session->busy;bool has=session->original!=nullptr;
 for(auto* b:{&analyseButton,&alignButton,&selectedButton,&exportButton,&compareButton})b->setEnabled(has&&!busy);
 undoButton.setEnabled(session->canUndo());redoButton.setEnabled(session->canRedo());
 bool ara=false;
#if JucePlugin_Enable_ARA
 ara=processor.isEditorView()||processor.isPlaybackRenderer();
#endif
 importButton.setEnabled(!ara&&!busy&&!processor.captureArmed);captureButton.setEnabled(!ara&&!busy);audition.setEnabled(!ara&&has&&!processor.captureArmed);captureButton.setButtonText(processor.captureArmed?"Finish capture":"Capture");
 compareButton.setToggleState(session->compare.load(),juce::dontSendNotification);
 for(auto* c:std::initializer_list<juce::Component*>{&sensitivity,&strength,&humanize,&tolerance,&swing,&offset,&grid,&mode,&rhythm,&presets,&sampleAccurate,&breath,&consonant,&vowel,&emotion,&settingsButton})c->setEnabled(!busy);
 repaint();waveform.repaint();overview.repaint();
}
void NooriEditor::chooseFile(bool save){chooser=std::make_unique<juce::FileChooser>(save?"Export corrected 24-bit WAV":"Import mono or stereo vocal",juce::File(),save?"*.wav":"*.wav;*.aif;*.aiff;*.flac");auto flags=save?juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting:juce::FileBrowserComponent::openMode|juce::FileBrowserComponent::canSelectFiles;chooser->launchAsync(flags,[safe=juce::Component::SafePointer<NooriEditor>(this),save](const juce::FileChooser& fc){if(!safe)return;auto file=fc.getResult();if(file==juce::File())return;if(save)safe->processor.exportFile(file,safe->session);else safe->processor.importFile(file);});}
void NooriEditor::scrollBarMoved(juce::ScrollBar*,double start){viewStart=start;waveform.repaint();overview.repaint();}
void NooriEditor::updateScroll(){scroll.setRangeLimits(0,1);scroll.setCurrentRange(viewStart,viewFraction,juce::dontSendNotification);}
