NooriEditor::WaveView::WaveView(NooriEditor& e,bool o):editor(e),overview(o){setMouseCursor(juce::MouseCursor::CrosshairCursor);}
noori::Sample NooriEditor::WaveView::sampleAt(float x)const {if(!editor.session->original)return 0;double start=overview?0:editor.viewStart,frac=overview?1:editor.viewFraction;return (noori::Sample)std::llround((start+double(x)/getWidth()*frac)*editor.session->original->length());}
float NooriEditor::WaveView::xAt(noori::Sample s)const {if(!editor.session->original)return 0;return float((double(s)/editor.session->original->length()-(overview?0:editor.viewStart))/(overview?1:editor.viewFraction)*getWidth());}
void NooriEditor::WaveView::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff15121e));auto* audio=editor.session->displayed();if(!audio){if(!overview){text(g,"Your vocal. Its original emotion.",{0,getHeight()/2-26,getWidth(),30},23,ink,juce::Justification::centred);text(g,"Import audio, capture the insert input, or select an ARA event.",{0,getHeight()/2+10,getWidth(),25},14,muted,juce::Justification::centred);}return;}
 const int top=overview?0:30;float center=(getHeight()+top)*.5f,amp=(getHeight()-top)*.42f;
 if(!overview){const auto start=sampleAt(0),end=sampleAt((float)getWidth());auto& map=editor.session->timeline;auto origin=editor.session->origin;auto s=editor.session->settings;double step=4./s.division;if(s.rhythm==noori::Settings::Rhythm::triplet)step*=2./3;if(s.rhythm==noori::Settings::Rhythm::dotted)step*=1.5;auto first=(long long)std::floor(map.quarterAt(start+origin)/step)-1;auto last=(long long)std::ceil(map.quarterAt(end+origin)/step)+1;for(auto k=first;k<=last&&k<first+2000;++k){double q=k*step+(k%2?s.swing*step:0);float x=xAt(map.sampleAt(q)-origin+(noori::Sample)std::llround(s.offsetMs*.001*audio->sampleRate));g.setColour(k%editor.session->settings.division==0?line:line.withAlpha(.35f));g.drawVerticalLine((int)x,(float)top,(float)getHeight());if(k%2==0)text(g,juce::String(q,1),{(int)x+4,2,65,21},11,muted);}}
 for(int x=0;x<getWidth();++x){auto first=std::clamp<noori::Sample>(sampleAt((float)x),0,audio->length()-1),last=std::clamp<noori::Sample>(sampleAt((float)(x+1)),first+1,audio->length());float low=0,high=0;double energy=0;int count=0;auto stride=std::max<noori::Sample>(1,(last-first)/64);for(auto i=first;i<last;i+=stride){float v=audio->channels[0][(std::size_t)i];low=std::min(low,v);high=std::max(high,v);energy+=double(v)*v;++count;}g.setColour(overview?muted:editor.levelView?juce::Colour(0xff65cfad):purple.withAlpha(.72f));if(editor.levelView&&!overview){float rms=(float)std::sqrt(energy/std::max(1,count));g.drawVerticalLine(x,center-rms*amp*2,center+rms*amp*2);}else g.drawVerticalLine(x,center-high*amp,center-low*amp);}
 if(!overview){for(std::size_t i=0;i<editor.session->attacks.size();++i){auto a=editor.session->attacks[i];auto target=(int)i==dragging?dragTarget:a.target;float x=xAt(target);if(x<0||x>getWidth())continue;g.setColour(a.selected?juce::Colour(0xffffce79):purple);g.drawVerticalLine((int)x,(float)top,(float)getHeight());g.fillEllipse(x-3,top+2,6,6);if(a.target!=a.source){g.setColour(muted.withAlpha(.3f));g.drawVerticalLine((int)xAt(a.source),(float)top,(float)getHeight());}}}
 else {g.setColour(purple.withAlpha(.2f));g.fillRect((float)(editor.viewStart*getWidth()),0.f,(float)(editor.viewFraction*getWidth()),(float)getHeight());g.setColour(purple);g.drawRect((float)(editor.viewStart*getWidth()),0.f,(float)(editor.viewFraction*getWidth()),(float)getHeight(),1.f);}
 const auto position=editor.processor.hostSample.load();const double srRatio=audio->sampleRate/std::max(1.,editor.processor.getSampleRate());auto at=(noori::Sample)std::llround(position*srRatio)-editor.session->origin;auto px=xAt(at);if(px>=0&&px<getWidth()){g.setColour(juce::Colour(0xffffd87b));g.drawVerticalLine((int)px,0.f,(float)getHeight());}
}
void NooriEditor::WaveView::mouseDown(const juce::MouseEvent& e){if(!editor.session->original||editor.session->busy)return;if(overview){mouseDrag(e);return;}float best=9;int nearest=-1;for(std::size_t i=0;i<editor.session->attacks.size();++i){auto d=std::abs(xAt(editor.session->attacks[i].target)-e.position.x);if(d<best){best=d;nearest=(int)i;}}if(nearest>=0){editor.session->setSelected((std::size_t)nearest,e.mods.isShiftDown());editor.selectedMarker=nearest;dragging=nearest;dragTarget=editor.session->attacks[(std::size_t)nearest].target;repaint();}}
void NooriEditor::WaveView::mouseDrag(const juce::MouseEvent& e){if(!editor.session->original)return;if(overview){editor.viewStart=std::clamp(double(e.position.x)/getWidth()-editor.viewFraction*.5,0.,1-editor.viewFraction);editor.updateScroll();editor.waveform.repaint();repaint();}else if(dragging>=0){try{auto m=noori::moveAttack(editor.session->attacks,(std::size_t)dragging,sampleAt(e.position.x),editor.session->original->length(),editor.session->settings.maxStretch);dragTarget=m[(std::size_t)dragging].target;repaint();}catch(...){}}}
void NooriEditor::WaveView::mouseUp(const juce::MouseEvent&){if(dragging>=0){if(dragTarget!=editor.session->attacks[(std::size_t)dragging].target)editor.session->move((std::size_t)dragging,dragTarget);dragging=-1;}}
void NooriEditor::WaveView::mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& d){if(e.mods.isCtrlDown())editor.zoom.setValue(editor.zoom.getValue()*(d.deltaY>0?1.15:1/1.15));else {editor.viewStart=std::clamp(editor.viewStart-d.deltaY*editor.viewFraction*.3,0.,1-editor.viewFraction);editor.updateScroll();editor.waveform.repaint();editor.overview.repaint();}}
